test_that("ClassicalNetworkMetaAnalysis (analysis 3) results match", {

  # Load from JASP example file
  jaspFile <- testthat::test_path("jaspfiles", "other", "Network Meta-Analysis - Senn2013.jasp")
  opts <- jaspTools::analysisOptions(jaspFile)[[3]]
  dataset <- jaspTools::extractDatasetFromJASPFile(jaspFile)

  # Encode and run analysis
  encoded <- jaspTools:::encodeOptionsAndDataset(opts, dataset)
  set.seed(1)
  results <- jaspTools::runAnalysis("ClassicalNetworkMetaAnalysis", encoded$dataset, encoded$options, encodedDataset = TRUE)

  table <- results[["results"]][["modelSummaryContainer"]][["collection"]][["modelSummaryContainer_inputSummaryTable"]][["data"]]
  jaspTools::expect_equal_tables(table,
    list(15, 26, 28, 1, 10))

  table <- results[["results"]][["modelSummaryContainer"]][["collection"]][["modelSummaryContainer_testsTable"]][["data"]]
  jaspTools::expect_equal_tables(table,
    list(7.87136855204678e-13, "Q(18) = 96.99", "Total", 1.72394355555806e-11,
     "Q(11) = 74.46", "Within designs", 0.00205701423800982, "Q(7) = 22.53",
     "Between designs"))

  table <- results[["results"]][["treatmentEffectsContainer"]][["collection"]][["treatmentEffectsContainer_treatmentEffectsTable"]][["data"]]
  jaspTools::expect_equal_tables(table,
    list("Acarbose", -0.827368972010615, -1.04006592064385, 2.45827181298008e-14,
     0.10852084543949, -7.62405571629968, -0.614672023377378, "Benfluorex",
     -0.905186449417243, -1.15428049597607, 1.06108823903706e-12,
     0.127091134594133, -7.12234139940578, -0.65609240285841, "Metformin",
     -1.11411018904417, -1.23094653810733, 6.02472049384277e-78,
     0.05961147754997, -18.6895248169324, -0.997273839981011, "Miglitol",
     -0.943932962855599, -1.19266438828359, 1.02189127585687e-13,
     0.126906120413413, -7.43804128422343, -0.695201537427605, "Pioglitazone",
     -1.0664331068707, -1.21509148860612, 6.66727168833368e-45, 0.0758475068460534,
     -14.0602262515394, -0.917774725135277, "Rosiglitazone", -1.20184201070072,
     -1.29525813817446, 2.6846146799665e-140, 0.0476621653308935,
     -25.215849979894, -1.10842588322697, "Sitagliptin", -0.569999999999995,
     -0.823031350404116, 1.00925028375785e-05, 0.1291, -4.41518202943451,
     -0.316968649595875, "Sulfonylurea", -0.439497150629668, -0.618792941696559,
     1.5526000621015e-06, 0.0914791253722792, -4.80434360124357,
     -0.260201359562776, "Vildagliptin", -0.700000000000011, -0.94950341523196,
     3.82337533166561e-08, 0.1273, -5.49882168106843, -0.450496584768062
    ))

